const PUBLIC_HEADPHONES = HEADPHONES.filter(h => CATALOG_REVIEW[h.id]?.catalogStatus === "available");
function catalogSpec(h, field) {
  if (CATALOG_REVIEW[h.id]?.pendingSpecs.includes(field)) return 'Em revisão';
  return h.specs[field] || '—';
}
function catalogPrice(h) {
  const quote = currentPriceQuote(h.id);
  return quote ? quote.amount.toLocaleString('pt-BR', {style:'currency',currency:'BRL'}) : 'Consultar loja';
}
